class Test_HornSchunckHornSchunck:
    @pytest.mark.valid
    @pytest.mark.smoke
    def test_basic_flow_estimation(self):
        # Arrange
        image0 = np.array([[0, 0, 2], [0, 0, 2]])
        image1 = np.array([[0, 2, 0], [0, 2, 0]])
        alpha = 0.1
        num_iter = 110
        expected_horizontal_flow = np.array([[0, -1, -1], [0, -1, -1]])
        expected_vertical_flow = np.array([[0, 0, 0], [0, 0, 0]])

        # Act
